WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') ma_dvcs,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' allb FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid),q AS (SELECT 'IQC' loai,ma_dvcs,stt_rec,ngay_ct,so_ct,ma_vt,ma_lo,so_luong,so_luong_ok,so_luong_ng,ket_qua,status FROM public.phiqc UNION ALL SELECT 'IPQC',ma_dvcs,stt_rec,ngay_ct,so_ct,ma_vt,ma_lo,so_luong,so_luong_ok,so_luong_ng,ket_qua,status FROM public.phpqc) SELECT q.loai,q.ma_dvcs,q.stt_rec,q.ngay_ct,q.so_ct,q.ma_vt,q.ma_lo,q.so_luong,q.so_luong_ok,q.so_luong_ng,q.ket_qua,q.status,count(*) OVER() total FROM q CROSS JOIN s WHERE s.ok IS NOT NULL AND q.ngay_ct BETWEEN s.d1 AND s.d2 AND(s.ma_dvcs='' OR q.ma_dvcs=ANY(string_to_array(s.ma_dvcs,',')))AND(s.allb OR q.ma_dvcs=ANY(string_to_array(s.bs,','))) ORDER BY q.ngay_ct DESC,q.so_ct LIMIT(SELECT lim FROM p);
